using UnityEngine;
using System.Linq;
namespace LightingBlocks
{
    // Clips are generated by Tools/audio/build_audio.py and loaded from
    // Resources so the code-generated scenes need no wiring in the setup scripts.
    public static class GameAudio
    {
        public const float MusicVolume = .10f;
        public const float SfxVolume = .18f;

        static AudioClip[] footsteps;
        static AudioClip grab;
        static AudioSource music;

        public static AudioClip[] Footsteps
        {
            get
            {
                if (footsteps != null) return footsteps;
                var list = new System.Collections.Generic.List<AudioClip>();
                for (int i = 1; i <= 5; i++)
                {
                    var clip = Resources.Load<AudioClip>("Audio/SFX/footstep_stone_" + i.ToString("00"));
                    if (clip != null) list.Add(clip);
                }
                footsteps = list.ToArray();
                
                return footsteps;
            }
        }

        static AudioClip Trim(AudioClip src, float seconds)
{
    if (src == null) return null;
    int frames = Mathf.Min(src.samples, (int)(seconds * src.frequency));
    var data = new float[frames * src.channels];
    src.GetData(data, 0);
    int fade = Mathf.Min(frames, src.frequency / 100) * src.channels; // 10 ms
    for (int i = 0; i < fade; i++) data[data.Length - 1 - i] *= (float)i / fade;
    var clip = AudioClip.Create(src.name + "_trim", frames, src.channels, src.frequency, false);
    clip.SetData(data, 0);
    return clip;
}

        public static AudioClip Grab => grab != null ? grab : grab = Resources.Load<AudioClip>("Audio/SFX/Bloques");

        // Pitch hooks for the step and grab clips; 1 plays the file as recorded.
        public static float StepPitch => 1f;
        public static float GrabPitch(PullableBox box) =>
            box != null && box.GetComponent<BridgeBlock>() != null ? 1f : 1f;

        public static void PlayMusic(string clipName)
        {
            var clip = Resources.Load<AudioClip>("Audio/Music/" + clipName);
            if (clip == null) return;
            if (music == null)
            {
                var host = new GameObject("Music");
                host.transform.SetParent(null);
                music = host.AddComponent<AudioSource>();
                ForestSoundscape.Route(music,"Music"); music.spatialBlend = 0; music.loop = true; music.volume = MusicVolume;
                music.playOnAwake = false; music.priority = 0;
            }
            if (music.clip == clip && music.isPlaying) return;
            music.clip = clip; music.Play();
        }

        public static void StopMusic() { if (music != null) music.Stop(); }
    }
}
